export const getHiddenColumnIds = (
  allColumnIds: string[],
  visibleColumns: string[],
): string[] => {
  const visibleSet = new Set(visibleColumns);

  return allColumnIds.filter((columnId) => !visibleSet.has(columnId));
};

export const getSyncedVisibleColumns = (
  visibleColumns: string[],
  allColumnIds: string[],
): string[] => {
  if (!allColumnIds.length) {
    return visibleColumns;
  }

  return visibleColumns.filter((columnId) => allColumnIds.includes(columnId));
};
